47	\N	[Category.원상복구 요약 : 계약 종료 시 임차인의 원상복구 의무와 임대인의 보증금 반환 및 공제 사항을 정합니다. 원문 : 제 5조 (계약의 종료) 임대차계약이 종료된 경우에 임차인은 위 부동산을 원상으로 회복하여 임대인에게 반환한다. 이러한 경우 임대인은 보증금을 임차인에게 반환하고, 연체 임대료 또는 손해배상금이 있을 때는 이들을 제하고 그 잔액을 반환한다.]	[0.008211807,0.011447828,-0.0017405458,-0.06913544,0.012635134,-0.0058034714,-0.008658124,0.005991752,0.009864419,-0.007122763,-0.009509585,0.028807137,-0.003202449,-0.00254618,0.14799485,0.0065702433,0.008262277,0.0032020556,-0.0112537,-0.015342847,0.006839471,0.0077364896,0.03155471,-0.0023449045,-0.004779008,-0.006969604,0.005099879,0.03388567,0.032007825,-0.012514123,-0.017565725,0.01295603,0.011666121,0.014082077,0.014244709,0.03152468,0.010056958,-0.024439933,-0.0065136687,0.016964631,-0.035731383,0.009787637,0.0052075707,0.006927935,0.013817627,-0.0026056853,0.019469205,0.00074775226,-0.009433119,0.014425777,-0.008377651,-0.034918286,-0.0043445504,-0.17955175,-0.022728499,-0.0040226756,-0.003569583,-0.018399922,-0.012470027,-0.008155677,-0.009850886,0.023770452,-0.002984877,-0.01431458,-0.001202142,-0.018487534,0.014269881,-0.00011907204,-0.021885645,-0.008053889,0.006702529,0.02785593,-0.009317509,-0.019477582,0.0051331143,-0.033166867,-0.013903998,-0.0059912764,0.016043311,0.007396163,0.016775606,-0.0137163615,-0.006124755,-0.017385291,0.024809688,0.009729673,-0.012397265,-0.008276063,0.009167457,0.022649417,0.0042523323,-0.011084242,0.035754714,-0.0024309254,-0.008538855,0.021759141,0.0068479697,0.008209727,-0.030442202,-0.009685067,-0.0079020215,0.009466486,-0.0073417006,-0.021225858,0.007871491,0.012196474,0.012886857,0.005861679,-0.012900186,-0.004983722,0.008174826,-0.02664993,-0.023817683,0.0031069107,-0.018984716,-0.14483213,0.0050682123,0.022643976,0.0070298514,-0.025679315,0.017611003,0.0041934424,0.024218628,0.028444944,0.011918684,-0.014080911,-0.00013459583,0.00034940953,-0.008207311,-0.02042466,-0.0005784747,0.01060157,-0.019860838,0.0184086,-0.0071141208,0.03723764,0.00785954,-0.019663287,-0.002170103,-0.012413739,-0.008970012,0.01